parameters.jsCode:
const dados = $('Webhook Grupo').first().json.body;
const entregadores = $input.all().map(i => i.json);

if (!entregadores || entregadores.length === 0) {
  return [{ json: { ...dados, entregador_jid: null, entregador_nome: 'Entregador', entregador_id: null, sem_entregador: true } }];
}

function haversine(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat/2)**2 + Math.cos(lat1*Math.PI/180) * Math.cos(lat2*Math.PI/180) * Math.sin(dLon/2)**2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
}

const clienteLat = parseFloat(dados.lat);
const clienteLon = parseFloat(dados.long);
const clienteGeoValido = !Number.isNaN(clienteLat) && !Number.isNaN(clienteLon);

let melhor = null;
let menorDist = Infinity;

if (!clienteGeoValido) {
  console.warn('Geocodificacao do cliente ausente/invalida (lat=' + dados.lat + ', long=' + dados.long + ') - usando primeiro entregador disponivel em vez de distancia.');
  melhor = entregadores[0];
  menorDist = null;
} else {
  for (const e of entregadores) {
    const lat = parseFloat(e.lat);
    const long = parseFloat(e.long);
    if (Number.isNaN(lat) || Number.isNaN(long)) continue;
    const dist = haversine(clienteLat, clienteLon, lat, long);
    if (dist < menorDist) { menorDist = dist; melhor = e; }
  }

  if (!melhor) {
    melhor = entregadores[0];
    menorDist = null;
  }
}

return [{ json: { ...dados, entregador_jid: melhor.jid_whatsapp, entregador_nome: melhor.nome, entregador_id: melhor.id, distancia_km: menorDist !== null ? menorDist.toFixed(1) : null, sem_entregador: false } }];

